"""Durable generated bytes enter existing native media contracts, never a render job.

Caller locks the operation for mutation and commits provider completion before
admission. Storage errors retain those bytes; caller commits the failure code.
"""

from __future__ import annotations

import hashlib
import io
import tempfile
import uuid
import wave
from datetime import UTC, datetime
from pathlib import Path

from PIL import Image
from sqlalchemy import select, update
from sqlalchemy.orm import Session

from app import storage
from app.models import ContentPlan, GeneratedMediaOperation, PlanItem, PlanItemAsset
from app.services.generated_asset_contracts import MAX_AUDIO_BYTES, MAX_IMAGE_BYTES, GeneratedAsset
from app.services.generative_upload_paths import DIRECT_VOICEOVER_PREFIX


def _owned(db, operation, owner_id, plan_item_id):
    if operation.user_id != owner_id or operation.plan_item_id != plan_item_id:
        raise ValueError("generated media owner mismatch")
    owned = db.scalar(
        select(PlanItem.id)
        .join(ContentPlan, PlanItem.content_plan_id == ContentPlan.id)
        .where(PlanItem.id == plan_item_id, ContentPlan.user_id == owner_id)
    )
    if owned is None:
        raise ValueError("generated media item owner mismatch")


def _inspect(content, mime, capability):
    if not content or len(content) > MAX_IMAGE_BYTES:
        raise ValueError("generated media bytes out of bounds")
    if capability in {"image", "image_edit"} and mime == "image/png":
        with Image.open(io.BytesIO(content)) as image:
            if image.format != "PNG" or image.size not in {
                (1024, 1024),
                (1024, 1536),
                (1536, 1024),
            }:
                raise ValueError("invalid generated image dimensions")
            width, height = image.size
            image.verify()
        with Image.open(io.BytesIO(content)) as image:
            image.load()
        return width, height, None
    if capability == "narration" and mime == "audio/wav":
        with wave.open(io.BytesIO(content), "rb") as audio:
            frames = audio.getnframes()
            if (
                audio.getnchannels(),
                audio.getsampwidth(),
                audio.getframerate(),
                audio.getcomptype(),
            ) != (1, 2, 24000, "NONE") or not 0 < frames <= MAX_AUDIO_BYTES // 2:
                raise ValueError("invalid generated narration format")
            if len(audio.readframes(frames)) != frames * 2:
                raise ValueError("truncated generated narration")
            return None, None, frames / 24000
    raise ValueError("generated media capability and mime mismatch")


def persist_generated_asset(
    db: Session,
    operation: GeneratedMediaOperation,
    asset: GeneratedAsset,
    *,
    owner_id: uuid.UUID,
    plan_item_id: uuid.UUID,
) -> GeneratedMediaOperation:
    _owned(db, operation, owner_id, plan_item_id)
    digest = hashlib.sha256(asset.content).hexdigest()
    if operation.state in {"provider_complete", "ready"}:
        if operation.content_sha256 != digest:
            raise ValueError("generated media result changed")
        return operation
    if operation.state != "submitting":
        raise ValueError("generated media is not submitting")
    _, _, duration = _inspect(asset.content, asset.mime_type, operation.capability)
    operation.pending_content = asset.content
    operation.mime_type = asset.mime_type
    operation.content_sha256 = digest
    operation.model = asset.model
    operation.usage = asset.usage
    operation.provider_request_id = asset.provider_request_id
    operation.editable_title = asset.editable_title
    operation.duration_s = duration
    operation.state = "provider_complete"
    operation.failure_code = None
    db.flush()
    return operation


def admit_generated_asset(
    db: Session, operation: GeneratedMediaOperation, *, owner_id: uuid.UUID, plan_item_id: uuid.UUID
) -> GeneratedMediaOperation:
    _owned(db, operation, owner_id, plan_item_id)
    if operation.state == "ready":
        return operation
    if operation.state != "provider_complete" or operation.pending_content is None:
        raise ValueError("generated media has no completed provider result")
    if operation.expires_at and operation.expires_at <= datetime.now(UTC):
        raise ValueError("generated media result expired")
    content = operation.pending_content
    if hashlib.sha256(content).hexdigest() != operation.content_sha256:
        raise ValueError("generated media digest mismatch")
    width, height, duration = _inspect(content, operation.mime_type, operation.capability)
    image = operation.capability in {"image", "image_edit"}
    path = (
        f"users/{owner_id}/plan/{plan_item_id}/pool/{operation.id}/{operation.content_sha256}.png"
        if image
        else f"{DIRECT_VOICEOVER_PREFIX}{owner_id}/{operation.id}/{operation.content_sha256}.wav"
    )
    try:
        with tempfile.TemporaryDirectory(prefix="generated-media-") as directory:
            local = Path(directory) / "asset"
            local.write_bytes(content)
            metadata = storage.upload_local_file_immutable(str(local), path, operation.mime_type)
            if not metadata.generation or metadata.size != len(content):
                raise ValueError("generated media storage identity mismatch")
            # Immutable retries must prove bytes, not merely equal length.
            storage.download_generation_to_file(
                path, str(local), generation=str(metadata.generation)
            )
            if (
                local.stat().st_size != len(content)
                or hashlib.sha256(local.read_bytes()).hexdigest() != operation.content_sha256
            ):
                raise ValueError("generated media stored digest mismatch")
    except Exception:
        operation.failure_code = "storage_failed"
        raise
    if image:
        asset = PlanItemAsset(
            id=uuid.uuid4(),
            user_id=owner_id,
            plan_item_id=plan_item_id,
            kind="image",
            status="ready",
            media_status="ready",
            gcs_path=path,
            gcs_generation=str(metadata.generation),
            upload_content_type="image/png",
            upload_size_bytes=len(content),
            aspect=width / height,
            source_filename="generated.png",
            content_hash=operation.content_sha256,
            analysis={
                "width": width,
                "height": height,
                "source": "generated",
                "model": operation.model,
            },
            user_context=operation.editable_title or None,
        )
        db.add(asset)
        db.flush([asset])
        operation.asset_id = asset.id
    operation.output_path = path
    operation.output_generation = str(metadata.generation)
    operation.duration_s = duration
    operation.pending_content = None
    operation.state = "ready"
    operation.failure_code = None
    db.flush()
    return operation


def cleanup_expired_generated_media(db: Session, *, now: datetime | None = None) -> int:
    """Bound retained provider bytes without deleting owned admitted objects."""
    result = db.execute(
        update(GeneratedMediaOperation)
        .where(
            GeneratedMediaOperation.expires_at <= (now or datetime.now(UTC)),
            GeneratedMediaOperation.pending_content.is_not(None),
        )
        .values(pending_content=None, state="failed", failure_code="result_expired")
    )
    return result.rowcount
